-- Check how many observatories have signals vs total
SELECT COUNT(DISTINCT o.observstation) as obs_with_signals FROM signals s
JOIN telescopes t ON s.telescref = t.telescregistry
JOIN observatories o ON t.observstation = o.observstation;

SELECT COUNT(*) as total_obs FROM observatories;

SELECT COUNT(DISTINCT o.observstation) as obs_with_signals FROM signals s
JOIN telescopes t ON s.telescref = t.telescregistry
JOIN observatories o ON t.observstation = o.observstation;
